export function nextStep(current: number, total: number, valid: boolean) {
  if (!Number.isInteger(current) || current < 0 || current >= total)
    throw new Error('단계가 유효하지 않습니다.');
  if (!valid) return current;
  return Math.min(current + 1, total - 1);
}
// 단계 이동 이후 제목에 포커스를 옮기고 남은 단계를 안내합니다.

type Answers = { kind: 'person' | 'company'; companyName?: string };
export function sanitizeAnswers(answers: Answers) {
  if (answers.kind === 'person') return { kind: answers.kind };
  const companyName = answers.companyName?.trim();
  if (!companyName) throw new Error('회사명을 입력하세요.');
  return { kind: answers.kind, companyName };
}

export function validateDisplayName(value: string) {
  const normalized = value.trim();
  if (!normalized) return { valid: false, message: '이름을 입력하세요.' };
  if ([...normalized].length > 40)
    return { valid: false, message: '40자 이내로 입력하세요.' };
  return { valid: true, value: normalized };
}

type Draft = { formVersion: string; savedAt: number; answers: Record<string, string> };
export function resumable(draft: Draft, version: string, now: number) {
  const maxAge = 7 * 24 * 60 * 60 * 1000;
  return draft.formVersion === version && draft.savedAt <= now
    && now - draft.savedAt < maxAge;
}
// 실제 보존기간은 수집 목적과 사용자 안내에 맞춰 정합니다.

type Branch = { value: string; next: string };
export function nextQuestion(answer: string, branches: Branch[], fallback: string) {
  return branches.find(branch => branch.value === answer)?.next ?? fallback;
}
// 게시 전 next와 fallback이 실제 질문 또는 명시적 종료 ID인지 검사합니다.

export function percent(selected: number, exposed: number) {
  if (!Number.isInteger(selected) || !Number.isInteger(exposed)
    || selected < 0 || exposed < selected) throw new Error('집계 값 오류');
  return exposed === 0 ? null : Math.round(selected / exposed * 1000) / 10;
}
// 질문별 응답자 비율이며 소수 표본 보호는 별도로 적용합니다.
